static int qiban_ensure_dir(FAR const char *path)
{
  int ret;

  ret = mkdir(path, 0777);
  if (ret < 0 && errno != EEXIST)
    {
      fprintf(stderr, "failed to create %s: %d\n", path, errno);
      return -errno;
    }

  return OK;
}

