static int qiban_make_temp_path(FAR const char *dst_path,
                                FAR char *buffer, size_t buffer_size)
{
  int written;

  written = snprintf(buffer, buffer_size, "%s.%ld.tmp",
                     dst_path, (long)getpid());
  if (written < 0 || written >= (int)buffer_size)
    {
      return -ENAMETOOLONG;
    }

  return OK;
}

